<template><div class="partner-page"><NavbarPublic/><main class="container py-5 mt-5"><div v-if="loading" class="text-center text-white py-5">Carregando parceiro...</div><div v-else-if="p" class="partner-shell"><div class="cover" :style="coverStyle"><div class="shade"></div><div class="identity"><img v-if="p.logoUrl" :src="img(p.logoUrl)"><div><small>PARCEIRO SEVEN SHOWS</small><h1>{{p.advertiserName}}</h1><p v-if="p.city">{{p.city}}<span v-if="p.state"> - {{p.state}}</span></p></div></div></div><div class="content"><h3>{{p.title}}</h3><p>{{p.description}}</p><div class="actions"><button v-if="p.whatsApp" @click="go('whatsapp')" class="btn btn-success btn-lg"><i class="ri-whatsapp-line"></i> Falar no WhatsApp</button><button v-if="p.instagramUrl" @click="go('instagram')" class="btn btn-outline-light btn-lg"><i class="ri-instagram-line"></i> Instagram</button><button v-if="p.websiteUrl" @click="go('website')" class="btn btn-outline-primary btn-lg"><i class="ri-global-line"></i> Site</button></div></div></div></main></div></template>
<script>import axios from'axios';import NavbarPublic from'@/components/public/NavbarPublic.vue';export default{name:'ParceiroPublico',components:{NavbarPublic},data(){return{p:null,loading:true}},computed:{coverStyle(){let u=this.img(this.p?.desktopImageUrl||this.p?.mobileImageUrl);return{backgroundImage:u?`url(${u})`:''}}},async mounted(){try{this.p=(await axios.get(`${process.env.VUE_APP_API_BASE_URL}/advertising/public/partner/${this.$route.params.slug}`)).data}catch{this.p=null}finally{this.loading=false}},methods:{img(u){if(!u)return'';if(/^https?:/.test(u))return u;let b=(process.env.VUE_APP_API_BASE_URL||'').replace(/\/api\/?$/,'');return `${b}${u.startsWith('/')?'':'/'}${u}`},async go(c){try{await axios.post(`${process.env.VUE_APP_API_BASE_URL}/advertising/public/${this.p.id}/click?channel=${c}`)}catch{return}let u=c==='whatsapp'?`https://wa.me/${(this.p.whatsApp||'').replace(/\D/g,'')}?text=${encodeURIComponent(this.p.whatsAppMessage||'Olá! Vi sua publicidade no Seven Shows e gostaria de mais informações.')}`:c==='instagram'?this.p.instagramUrl:this.p.websiteUrl;if(u)window.open(u,'_blank','noopener')}}}</script>
<style scoped>.partner-page{min-height:100vh;background:#090b11;padding-top:25px}.partner-shell{overflow:hidden;border-radius:22px;border:1px solid #242833;background:#131520}.cover{height:360px;background-size:cover;background-position:center;position:relative;background-color:#171a24}.shade{position:absolute;inset:0;background:linear-gradient(0deg,rgba(8,9,14,.98),rgba(8,9,14,.1))}.identity{position:absolute;left:35px;bottom:30px;display:flex;align-items:center;gap:18px;color:#fff}.identity img{width:88px;height:88px;object-fit:contain;background:#fff;border-radius:16px;padding:5px}.identity small{color:#22d3d3;font-weight:800;letter-spacing:1.5px}.identity h1{font-size:38px;font-weight:800;margin:4px 0}.identity p{margin:0;color:#c4c8d0}.content{padding:35px;color:#fff}.content p{max-width:800px;color:#aeb4c0;font-size:16px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}@media(max-width:767px){.cover{height:420px}.identity{left:20px;right:20px;bottom:22px;align-items:flex-start}.identity h1{font-size:28px}.identity img{width:70px;height:70px}.content{padding:24px}}</style>
